'use strict';
const $=id=>document.getElementById(id),zh=new URL(location.href).searchParams.get('lang')==='zh-Hant';
const text=zh?{title:'賽馬賽果',private:'私人開發',notice:'以公開事實賽果建立的本機原型。來源授權仍未核實；此資料集只在本機提供。',meeting:'已匯入賽事日',race:'第',download:'下載此場賽果 · ZIP',scope:'僅涵蓋本次匯入賽事日的身份及賽果，並非完整馬匹或人物檔案。',headers:['名次','馬號','馬名','騎師','練馬師','檔位','時間（秒）','實際負磅（磅）','獨贏賠率'],back:'返回賽果'}:{title:'Racing results',private:'Private development',notice:$('notice').textContent,meeting:'Imported meeting',race:'Race',download:'Download this race · ZIP',scope:'Identity and appearances in this imported meeting only; this is not a complete participant profile.',headers:['Place','No.','Horse','Jockey','Trainer','Draw','Time (seconds)','Carried (lb)','Final win odds'],back:'Back to race'};
document.documentElement.lang=zh?'zh-Hant':'en';$('title').textContent=text.title;$('private-label').textContent=text.private;$('notice').textContent=text.notice;$('meeting-label').textContent=text.meeting;$('download').textContent=text.download;$('back').textContent=text.back;$('language').textContent=zh?'English':'繁中';$('language').onclick=()=>{const u=new URL(location.href);u.searchParams.set('lang',zh?'en':'zh-Hant');location.href=u;};
if(zh){$('eyebrow').textContent='公開事實 · 本機原型';document.querySelector('.skip').textContent='跳至賽果';$('races').setAttribute('aria-label','賽事');document.querySelector('.table-scroll').setAttribute('aria-label','賽果');}
let version,selectedRace,requestSequence=0;const names=p=>zh?p.nameZhHant||p.name:p.name;
async function get(path){const r=await fetch(path);const body=await r.json();if(!r.ok)throw Error(body.error?.code||'REQUEST_FAILED');return body;}
function cell(parent,value){const td=document.createElement('td');td.textContent=value??'—';parent.append(td);return td;}
function entity(parent,p){const button=document.createElement('button');button.type='button';button.textContent=names(p);button.onclick=()=>participant(p.id);cell(parent,'').append(button);}
async function loadMeeting(){const seq=++requestSequence;version=$('meeting').value;$('detail').hidden=true;$('participant').hidden=true;$('message').textContent=zh?'載入賽事…':'Loading races…';try{const body=await get('/api/v1/racing/races?version='+encodeURIComponent(version));if(seq!==requestSequence)return;const c=body.coverage;$('coverage').textContent=zh?`${c.observedRaces}/${c.expectedRaces} 場賽果 · ${c.resultRows} 行賽果 · 排位名單尚未獨立核對 · 非完整馬季`:`${c.observedRaces}/${c.expectedRaces} result races · ${c.resultRows} result rows · declarations not independently reconciled · not a complete season`;$('races').replaceChildren();for(const race of body.data.items){const b=document.createElement('button');b.textContent=zh?`第 ${race.number} 場`:`Race ${race.number}`;b.type='button';b.dataset.race=race.id;b.onclick=()=>showRace(race.id);$('races').append(b);}const requested=new URL(location.href).searchParams.get('race');await showRace(body.data.items.find(r=>r.id===requested)?.id||body.data.items[0].id);}catch(e){if(seq===requestSequence)$('message').textContent=e.message;}}
async function showRace(id){const seq=++requestSequence;selectedRace=id;$('message').textContent=zh?'載入賽果…':'Loading results…';$('participant').hidden=true;try{const body=await get('/api/v1/racing/races/'+encodeURIComponent(id)+'/results?version='+encodeURIComponent(version));if(seq!==requestSequence)return;const race=body.data;$('race-title').textContent=`${zh?'第 '+race.number+' 場':'Race '+race.number} · ${zh?race.nameZhHant:race.name}`;$('race-info').textContent=`${race.distanceM}m · ${zh?race.goingZhHant:race.goingRaw} · ${zh?race.courseZhHant:race.courseRaw}`;$('head').replaceChildren();const h=document.createElement('tr');for(const label of text.headers){const th=document.createElement('th');th.scope='col';th.textContent=label;h.append(th);}$('head').append(h);$('rows').replaceChildren();for(const r of race.results){const tr=document.createElement('tr');cell(tr,r.placingRaw);cell(tr,r.horseNumber);entity(tr,r.horse);entity(tr,r.jockey);entity(tr,r.trainer);cell(tr,r.draw);cell(tr,r.timeSeconds);cell(tr,r.weightLb);cell(tr,r.winOddsFinal);$('rows').append(tr);}$('caption').textContent=zh?`賽果：${race.results.length} 行`:`Published results: ${race.results.length} rows`;$('download').href='/api/v1/racing/exports?version='+encodeURIComponent(version)+'&raceId='+encodeURIComponent(id);$('provenance').textContent=(zh?'觀測時間：':'Observed: ')+race.provenance[0].observed+' · '+(zh?'版本：':'Version: ')+version;$('detail').hidden=false;$('message').textContent='';for(const b of $('races').children)b.setAttribute('aria-current',String(b.dataset.race===id));const u=new URL(location.href);u.searchParams.set('race',id);history.replaceState(null,'',u);}catch(e){if(seq===requestSequence){$('detail').hidden=true;$('message').textContent=e.message;}}}
async function participant(id){const seq=++requestSequence;try{const body=await get('/api/v1/racing/participants/'+encodeURIComponent(id)+'?version='+encodeURIComponent(version));if(seq!==requestSequence)return;$('detail').hidden=true;$('participant').hidden=false;$('participant-title').textContent=names(body.data.identity);$('participant-scope').textContent=text.scope;$('appearances').replaceChildren();for(const a of body.data.appearances){const b=document.createElement('button');b.textContent=`${text.race} ${a.raceNumber} · ${names(a.horse)} · ${a.placing??a.status}`;b.onclick=()=>showRace(a.raceId);$('appearances').append(b);}$('participant-title').tabIndex=-1;$('participant-title').focus();}catch(e){if(seq===requestSequence)$('message').textContent=e.message;}}
$('meeting').onchange=loadMeeting;$('back').onclick=()=>showRace(selectedRace);
(async()=>{try{const body=await get('/api/v1/racing/status');for(const m of body.data.meetings){const o=document.createElement('option');o.value=m.version;o.textContent=`${m.meeting.date} · ${m.meeting.venue==='HV'?(zh?'跑馬地':'Happy Valley'):(zh?'沙田':'Sha Tin')}`;$('meeting').append(o);}if(!$('meeting').options.length){$('message').textContent=zh?'尚未匯入賽事日。請先執行本機匯入指令。':'No imported meetings. Run the local import command first.';return;}await loadMeeting();}catch(e){$('message').textContent=e.message;}})();
